// Parse /continue command input
const body = $input.item.json.body || $input.item.json;
const query = body.query || body.text || '';
const userId = body.user || body.user_id || '';
const channel = body.channel || body.channel_id || '';
const threadTs = body.thread_ts || body.conversation_id || '';

// Extract optional conversation ID from command args
// Usage: /continue or /continue <thread_ts>
const args = query.replace(/^\/continue\s*/i, '').trim();
const targetThreadTs = args || threadTs;

return [{
  json: {
    userId,
    channel,
    threadTs: targetThreadTs,
    originalQuery: query,
    timestamp: new Date().toISOString()
  },
  pairedItem: { item: 0 }
}];

// Retrieve partial result from Redis cache
const timeoutHandler = require('./lib/timeout-handler');
const threadTs = $input.item.json.threadTs;

if (!threadTs) {
  return [{
    json: {
      found: false,
      error: 'No conversation ID provided. Use `/continue` in a thread or `/continue <thread_ts>`',
      threadTs: null
    },
    pairedItem: { item: 0 }
  }];
}

const partialResult = await timeoutHandler.getPartialResult(threadTs);

if (!partialResult) {
  return [{
    json: {
      found: false,
      error: 'No timed-out request found for this conversation. Partial results expire after 5 minutes.',
      threadTs
    },
    pairedItem: { item: 0 }
  }];
}

// Found partial result
return [{
  json: {
    found: true,
    partialResult,
    threadTs,
    canResume: partialResult.canResume || false,
    originalQuery: partialResult.query,
    toolName: partialResult.toolName,
    timedOutAt: partialResult.timedOutAt
  },
  pairedItem: { item: 0 }
}];

// Format "not found" error message for Slack
const error = $input.item.json.error;
const threadTs = $input.item.json.threadTs;

return {
  json: {
    channel: $('Parse Input').item.json.channel,
    thread_ts: threadTs,
    blocks: [
      {
        "type": "header",
        "text": {
          "type": "plain_text",
          "text": "❌ Cannot Continue",
          "emoji": true
        }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": error
        }
      },
      {
        "type": "context",
        "elements": [{
          "type": "mrkdwn",
          "text": "_Partial results are cached for 5 minutes after timeout._"
        }]
      }
    ],
    text: error
  }
};

// Resume tool execution from partial state
const partialResult = $input.item.json.partialResult;
const toolName = partialResult.toolName;
const originalQuery = partialResult.query;

// TODO: Implement tool-specific resume logic
// For now, return partial results with message

const partialData = partialResult.partialResult || {};

return {
  json: {
    resumed: true,
    toolName,
    originalQuery,
    partialData,
    message: `Resumed search for: "${originalQuery}". Processing...`
  }
};

// Format "cannot resume" message (no partial state saved)
const partialResult = $input.item.json.partialResult;
const toolName = partialResult.toolName;
const originalQuery = partialResult.query;
const timedOutAt = new Date(partialResult.timedOutAt).toLocaleString();

return {
  json: {
    channel: $('Parse Input').item.json.channel,
    thread_ts: $input.item.json.threadTs,
    blocks: [
      {
        "type": "header",
        "text": {
          "type": "plain_text",
          "text": "⏱️ Request Timed Out",
          "emoji": true
        }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": `Your previous request timed out, but no partial results were saved.\n\n*Original query:* ${originalQuery}\n*Tool:* \`${toolName}\`\n*Timed out at:* ${timedOutAt}`
        }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": "*Options:*\n• Try a more specific query\n• Break down your question into smaller parts\n• Contact support if the issue persists"
        }
      },
      {
        "type": "context",
        "elements": [{
          "type": "mrkdwn",
          "text": "_Resume is not available because the tool did not save intermediate results._"
        }]
      }
    ],
    text: `Request timed out: ${originalQuery}`
  }
};

// Format successful resume response for Slack
const resumeData = $input.item.json;
const originalQuery = resumeData.originalQuery;
const partialData = resumeData.partialData;

// Extract results from partial data (structure depends on tool)
const results = partialData.results || [];
const processedCount = results.length || 0;

let resultsText = '';
if (processedCount > 0) {
  resultsText = `\n*Partial results (${processedCount} items):*\n`;
  results.slice(0, 3).forEach((result, idx) => {
    resultsText += `${idx + 1}. ${result.title || result.document_name || 'Result ' + (idx + 1)}\n`;
  });
  if (processedCount > 3) {
    resultsText += `_...and ${processedCount - 3} more results_\n`;
  }
}

return {
  json: {
    channel: $('Parse Input').item.json.channel,
    thread_ts: $('Parse Input').item.json.threadTs,
    blocks: [
      {
        "type": "header",
        "text": {
          "type": "plain_text",
          "text": "✅ Resumed Previous Request",
          "emoji": true
        }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": `*Original query:* ${originalQuery}${resultsText}`
        }
      },
      {
        "type": "context",
        "elements": [{
          "type": "mrkdwn",
          "text": `⚡ Resumed at ${new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`
        }]
      }
    ],
    text: `Resumed: ${originalQuery}`
  }
};
